ALTER TABLE memories ADD superseded_by_id VARCHAR(36) NULL;
CREATE TABLE IF NOT EXISTS memory_settings (team_id VARCHAR(36), curation_enabled BOOLEAN DEFAULT FALSE NOT NULL, last_run_at BIGINT NULL, last_run_id VARCHAR(36) NULL, last_superseded INT DEFAULT 0 NOT NULL, last_queued INT DEFAULT 0 NOT NULL, CONSTRAINT pk_memory_settings PRIMARY KEY (team_id), CONSTRAINT fk_memory_settings_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS memory_curation_state (team_id VARCHAR(36), `scope` VARCHAR(16), owner_id VARCHAR(36) DEFAULT '', curated_at BIGINT NOT NULL, CONSTRAINT pk_memory_curation_state PRIMARY KEY (team_id, `scope`, owner_id));
CREATE TABLE IF NOT EXISTS memory_reviews (id VARCHAR(36), team_id VARCHAR(36) NOT NULL, `scope` VARCHAR(16) NOT NULL, owner_id VARCHAR(36) DEFAULT '' NOT NULL, older_id VARCHAR(36) NOT NULL, newer_id VARCHAR(36) NOT NULL, kind VARCHAR(16) NOT NULL, reason VARCHAR(200) NOT NULL, `status` VARCHAR(12) NOT NULL, created_at BIGINT NOT NULL, resolved_at BIGINT NULL, CONSTRAINT pk_memory_reviews PRIMARY KEY (id), CONSTRAINT fk_memory_reviews_older_id__id FOREIGN KEY (older_id) REFERENCES memories(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_memory_reviews_newer_id__id FOREIGN KEY (newer_id) REFERENCES memories(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE UNIQUE INDEX memory_review_pair ON memory_reviews (older_id, newer_id);
CREATE INDEX memory_review_queue ON memory_reviews (team_id, `status`, `scope`, owner_id, created_at);
CREATE INDEX memory_review_closed ON memory_reviews (`status`, resolved_at);
